() => { 
  const overlay = document.querySelector('[data-testid="subscription-overlay"], .subscription-overlay, [aria-label*="subscription" i]');
  const closeBtns = Array.from(document.querySelectorAll('button')).filter(b => b.getAttribute('aria-label')?.toLowerCase().includes('close') || b.textContent.toLowerCase().includes('close') || b.textContent.toLowerCase().includes('dismiss'));
  return { overlayFound: !!overlay, closeBtnCount: closeBtns.length, closeBtnLabels: closeBtns.map(b => b.getAttribute('aria-label') || b.textContent) };
}

() => { 
  // Try to find and click any close button
  const allBtns = Array.from(document.querySelectorAll('button, [role="button"], a'));
  const candidates = allBtns.filter(b => {
    const t = (b.getAttribute('aria-label') || '') + ' ' + b.textContent + ' ' + (b.getAttribute('title') || '');
    return /close|dismiss|cancel/i.test(t);
  });
  return candidates.map(b => ({tag: b.tagName, label: b.getAttribute('aria-label'), text: b.textContent.slice(0, 50)}));
}

() => {
  // Try to dismiss any overlay by various means
  // Click on backdrop or X button
  const dialogs = document.querySelectorAll('[role="dialog"]');
  // Press Escape
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
  // Try to remove overlay manually
  const overlay = document.querySelector('[class*="subscription" i], [data-testid*="subscription" i]');
  let found = false;
  if (overlay) {
    found = true;
    overlay.style.display = 'none';
  }
  return { dialogsCount: dialogs.length, overlayFound: found };
}

() => {
  // Try to find article content even with overlay
  const articles = document.querySelectorAll('article');
  const main = document.querySelector('main');
  let bodyText = '';
  if (main) {
    bodyText = main.innerText;
  } else if (articles.length) {
    bodyText = Array.from(articles).map(a => a.innerText).join('\n');
  }
  return bodyText.slice(0, 4000);
}

() => {
  // Try various methods to remove overlay
  const all = document.querySelectorAll('*');
  const overlay = Array.from(all).find(el => {
    const cls = el.className?.toString() || '';
    return /overlay|modal|subscription|paywall/i.test(cls) && el.querySelectorAll('button').length > 1;
  });

  // Hide any element with overlay/subscription/paywall class
  let removed = 0;
  document.querySelectorAll('*').forEach(el => {
    const cls = el.className?.toString() || '';
    if (/overlay|paywall|subscription-blocker|scrim/i.test(cls)) {
      el.style.cssText = 'display: none !important; visibility: hidden !important;';
      removed++;
    }
  });

  return { overlayFound: !!overlay, removed };
}

() => {
  // Find article element and extract text
  const article = document.querySelector('article');
  let result = '';
  if (article) {
    // Get all paragraphs and headings
    const els = article.querySelectorAll('p, h1, h2, h3, h4');
    result = Array.from(els).map(e => e.textContent.trim()).filter(t => t).join('\n\n');
  }
  return result.slice(0, 8000);
}

() => {
  // Get all paragraphs in the page body
  const paragraphs = document.querySelectorAll('p');
  return Array.from(paragraphs).map(p => p.textContent.trim()).filter(t => t && t.length > 20).slice(0, 30).join('\n\n');
}

() => {
  // BBC stores content in script tags as JSON
  const scripts = Array.from(document.querySelectorAll('script[type="application/json"], script#__NEXT_DATA__, script[data-testid]'));
  let result = '';
  scripts.forEach(s => {
    const text = s.textContent;
    if (text && text.includes('brexit')) {
      result += text.slice(0, 500) + '\n\n';
    }
  });

  // Also try data-testid="paragraph" or similar
  const testIds = document.querySelectorAll('[data-testid*="paragraph"], [data-testid*="article"], [data-testid*="body"]');
  const testIdsText = Array.from(testIds).map(e => e.textContent.trim()).slice(0, 20).join('\n\n');

  return { scriptsFound: scripts.length, scriptsPreview: result.slice(0, 1000), testIdsCount: testIds.length, testIdsText };
}

() => {
  // Get the full inner HTML of main element to understand the page structure
  const main = document.querySelector('main');
  if (main) {
    return { 
      html: main.outerHTML.slice(0, 8000), 
      bodyClasses: document.body.className,
      bodyText: document.body.innerText.slice(0, 3000)
    };
  }
  return { bodyText: document.body.innerText.slice(0, 3000) };
}

() => {
  // Look for the article body in script elements
  const results = [];
  document.querySelectorAll('script').forEach((s, i) => {
    const t = s.textContent;
    if (t && t.length > 500) {
      // Look for ones that might contain article content
      if (/brexit|economy|trade|impact/i.test(t)) {
        results.push({ idx: i, len: t.length, preview: t.slice(0, 200) });
      }
    }
  });
  return results.slice(0, 5);
}
